        String[] words = {"Level", "Java", "Noon", "Kayak", "Racing"};
        for (String w : words) {
            boolean isPalindrome = true;
            int left = 0;
            int right = w.length() - 1;
            while (left < right) {
                char a = Character.toLowerCase(w.charAt(left));
                char b = Character.toLowerCase(w.charAt(right));
                if (a != b) {
                    isPalindrome = false;
                    break;
                }
                left++;
                right--;
            }
            System.out.println(w + " " + isPalindrome);
        }
    }
}
